def compute(vars):
    total_shares = vars["v2"]
    shares_after_11_25 = vars["v1"]

    if total_shares == 0:
        return None

    proportion = shares_after_11_25 / total_shares
    percentage = proportion * 100

    return {
        "value": percentage,
        "trace": {
            "shares_after_11_25": shares_after_11_25,
            "total_shares": total_shares,
            "proportion": proportion,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
